export function computeViewerInitials(name?: string | null): string {
    const clean = (name ?? '').trim();
    if (!clean) return 'UV';
    const parts = clean.split(/\s+/).filter(Boolean);
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return `${parts[0][0] ?? ''}${parts[parts.length - 1][0] ?? ''}`.toUpperCase();
}

export function formatReceiptClock(iso?: string | null): string | null {
    if (!iso) return null;
    const date = new Date(iso);
    if (Number.isNaN(date.getTime())) return null;
    const hh = String(date.getHours()).padStart(2, '0');
    const mm = String(date.getMinutes()).padStart(2, '0');
    return `${hh}:${mm}`;
}

/**
 * Merges server-persisted messages with FIFO client outbox entries (`sending` / `failed`),
 * suppressing transient duplicates if a WebSocket frame arrives slightly before HTTP settles.
 */
export function mergeMessagesWithOutbox<T extends ReceiptBearingMessage>(
    persisted: readonly T[],
    outbox: readonly OutboxQueueEntry[],
    scopeKey: string | null | undefined,
): T[] {
    if (!scopeKey || outbox.length === 0) return [...persisted];
    const scoped = outbox.filter((item) => item.scopeKey === scopeKey);
    if (scoped.length === 0) return [...persisted];

    const matchedPersistedIds = new Set<number>();
    const remainingOutbox: OutboxQueueEntry[] = [];

    for (const entry of scoped) {
        if (entry.status === 'sending') {
            const entryMs = Date.parse(entry.createdAt);
            const match = persisted.find(
                (msg) =>
                    !matchedPersistedIds.has(msg.id) &&
                    msg.senderRole === entry.senderRole &&
                    msg.content === entry.content &&
                    (Number.isNaN(entryMs) || Date.parse(msg.createdAt) >= entryMs - 5_000),
            );
            if (match) {
                matchedPersistedIds.add(match.id);
                continue;
            }
        }
        remainingOutbox.push(entry);
    }

    if (remainingOutbox.length === 0) return [...persisted];

    const optimisticRows = remainingOutbox.map(
        (entry, index) =>
            ({
                id: -(index + 1) - Math.abs(hashClientKey(entry.clientKey)),
                senderRole: entry.senderRole,
                senderName: entry.senderName,
                content: entry.content,
                createdAt: entry.createdAt,
                deliveredAt: null,
                readAt: null,
                seenByName: null,
                clientKey: entry.clientKey,
                deliveryStatus: entry.status,
            }) as unknown as T,
    );

    return [...persisted, ...optimisticRows];
}

function hashClientKey(key: string): number {
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
        hash = (hash * 31 + key.charCodeAt(i)) | 0;
    }
    return Math.abs(hash % 1_000_000) + 1;
}

/**
 * Resolves Chat-TTA / Zalo-style message status:
 * - `sending` & `failed` render on EVERY message in that state.
 * - `sent` / `delivered` / `seen` render ONLY under the sender's latest persisted message.
 */
export function resolveSupportMessageReceipt(
    messages: readonly ReceiptBearingMessage[],
    index: number,
    myRole: 'VISITOR' | 'ADMIN',
    locale: 'vi' | 'en' | 'ja' = 'vi',
): ResolvedMessageReceipt | null {
    const msg = messages[index];
    if (!msg || msg.senderRole !== myRole) return null;
    const dict = LABELS[locale] ?? LABELS.vi;

    if (msg.deliveryStatus === 'sending') {
        return {
            status: 'sending',
            label: dict.sending,
            detail: null,
            viewerName: null,
            viewerInitials: null,
        };
    }

    if (msg.deliveryStatus === 'failed') {
        return {
            status: 'failed',
            label: dict.failed,
            detail: null,
            viewerName: null,
            viewerInitials: null,
        };
    }

    let lastPersistedMineIndex = -1;
    for (let i = messages.length - 1; i >= 0; i--) {
        if (messages[i].senderRole === myRole && !messages[i].deliveryStatus) {
            lastPersistedMineIndex = i;
            break;
        }
    }
    if (index !== lastPersistedMineIndex) return null;

    if (msg.readAt) {
        const viewerName =
            msg.seenByName?.trim() || (myRole === 'VISITOR' ? dict.defaultAdmin : dict.defaultVisitor);
        const time = formatReceiptClock(msg.readAt);
        return {
            status: 'seen',
            label: dict.seen,
            detail: dict.seenByAt(viewerName, time),
            viewerName,
            viewerInitials: computeViewerInitials(viewerName),
        };
    }

    if (msg.deliveredAt) {
        const time = formatReceiptClock(msg.deliveredAt);
        return {
            status: 'delivered',
            label: dict.delivered,
            detail: dict.deliveredAt(time),
            viewerName: null,
            viewerInitials: null,
        };
    }

    return {
        status: 'sent',
        label: dict.sent,
        detail: null,
        viewerName: null,
        viewerInitials: null,
    };
}
